/* MedAtlas 3.1 — interface de estudos com cache local vinculado à conta e sincronização externa. */
(() => {
  'use strict';
  const KEY = window.MedAtlasCloud.localKey;
  const subjectsDefault = ['Anatomia','Fisiologia','Patologia','Farmacologia','Clínica Médica','Cirurgia Geral','Pediatria','Ginecologia e Obstetrícia','Medicina Preventiva','Diagnóstico por Imagem'];
  const nav = [
    ['dashboard','⌂','Início'],['community','♡','Comunidade'],['profile','◉','Meu perfil'],['planner','▦','Planejar'],['cards','▤','Revisão'],['quiz','✎','Questões'],['errors','◈','Erros'],['roadmap','♧','Trilha'],['progress','▥','Evolução']
  ];
  const questionsDefault = [
    {id:'q1',subject:'Cardiologia',q:'Paciente com fibrilação atrial e resposta ventricular rápida apresenta hipotensão importante e rebaixamento do nível de consciência. Qual é a conduta imediata mais adequada?',o:['Adenosina em bolus','Cardioversão elétrica sincronizada','Aguardar controle espontâneo da frequência','Iniciar apenas anticoagulação oral'],a:1,why:'Instabilidade hemodinâmica associada a taquiarritmia com pulso exige cardioversão elétrica sincronizada imediata, com sedação quando viável.'},
    {id:'q2',subject:'Cirurgia Geral',q:'Qual achado semiológico é classicamente associado à irritação peritoneal no quadro de apendicite aguda?',o:['Sinal de Trousseau','Sinal de Blumberg','Sinal de Babinski','Sinal de Homans'],a:1,why:'O sinal de Blumberg descreve dor à descompressão brusca, indicativa de irritação peritoneal; não é exclusivo de apendicite.'},
    {id:'q3',subject:'Farmacologia',q:'Por que os inibidores da ECA e os bloqueadores do receptor de angiotensina II podem precipitar lesão renal aguda na estenose bilateral significativa das artérias renais?',o:['Por vasoconstrição da arteríola aferente','Por dilatação da arteríola eferente e redução da pressão intraglomerular','Por toxicidade tubular direta universal','Por aumento da síntese de angiotensina II'],a:1,why:'A redução do efeito da angiotensina II dilata a arteríola eferente e pode reduzir a taxa de filtração glomerular quando a perfusão depende desse mecanismo compensatório.'},
    {id:'q4',subject:'Clínica Médica',q:'Na investigação de ascite, qual valor do gradiente de albumina soro-ascite (GASA) sugere hipertensão portal?',o:['Menor que 0,5 g/dL','Menor que 1,1 g/dL','Maior ou igual a 1,1 g/dL','Exatamente 0 g/dL'],a:2,why:'Um GASA ≥ 1,1 g/dL sugere ascite associada à hipertensão portal, sendo necessário integrar o resultado ao contexto clínico.'},
    {id:'q5',subject:'Pediatria',q:'Na avaliação de uma criança com suspeita de desidratação, qual conjunto de achados sugere maior gravidade?',o:['Lágrimas presentes e mucosas úmidas','Alteração de consciência, perfusão periférica ruim e pulso fraco','Apetite preservado e diurese normal','Exame físico inteiramente normal'],a:1,why:'Alterações do estado mental e da perfusão são sinais de alarme para desidratação grave/choque e exigem avaliação imediata.'},
    {id:'q6',subject:'Ginecologia e Obstetrícia',q:'A partir de qual idade gestacional a hipertensão de início recente costuma orientar a investigação de pré-eclâmpsia?',o:['12 semanas','16 semanas','20 semanas','Somente após o parto'],a:2,why:'A pré-eclâmpsia geralmente é considerada após 20 semanas de gestação, associada a proteinúria ou sinais de disfunção orgânica; também pode surgir no puerpério.'},
    {id:'q7',subject:'Medicina Preventiva',q:'Qual medida descreve a proporção de pessoas que já possuem uma doença em um momento específico?',o:['Incidência acumulada','Prevalência pontual','Risco relativo','Razão de chances'],a:1,why:'A prevalência pontual representa os casos existentes em uma população em determinado instante.'},
    {id:'q8',subject:'Fisiologia',q:'Segundo o mecanismo de Frank-Starling, o aumento do enchimento ventricular, dentro de limites fisiológicos, tende a:',o:['Reduzir obrigatoriamente o volume sistólico','Aumentar a força de contração e o volume sistólico','Interromper a sístole','Diminuir sempre a pré-carga'],a:1,why:'O maior estiramento inicial das fibras miocárdicas aumenta a força de contração e o volume ejetado até certo limite.'},
    {id:'q9',subject:'Anatomia',q:'Qual estrutura atravessa o hiato esofágico do diafragma?',o:['Veia cava inferior','Aorta abdominal','Esôfago e troncos vagais','Nervo frênico isoladamente'],a:2,why:'O hiato esofágico, aproximadamente ao nível de T10, transmite o esôfago e troncos vagais.'},
    {id:'q10',subject:'Diagnóstico por Imagem',q:'Qual exame é usualmente a primeira linha na avaliação de nódulos tireoidianos?',o:['Ressonância de crânio','Ultrassonografia da tireoide','PET-CT em todos os casos','Angiografia cerebral'],a:1,why:'A ultrassonografia permite caracterizar nódulos e estratificar risco; TSH e contexto clínico orientam investigação adicional.'},
    {id:'q11',subject:'Patologia',q:'Qual padrão de necrose é tipicamente encontrado no infarto isquêmico do miocárdio?',o:['Necrose liquefativa','Necrose coagulativa','Necrose caseosa exclusivamente','Necrose gordurosa enzimática'],a:1,why:'A isquemia no miocárdio geralmente provoca necrose coagulativa, preservando temporariamente a arquitetura tecidual.'},
    {id:'q12',subject:'Clínica Médica',q:'Quais manifestações são mais sugestivas de pielonefrite aguda do que de cistite não complicada?',o:['Disúria isolada sem febre','Febre, dor lombar e dor à punho-percussão','Polaciúria isolada','Ausência completa de sintomas sistêmicos'],a:1,why:'Pielonefrite costuma cursar com sintomas sistêmicos, febre e dor em flanco, além de possíveis sintomas urinários.'},
    {id:'q13',subject:'Cardiologia',q:'Na ressuscitação cardiopulmonar de adultos, qual é a frequência recomendada para as compressões torácicas?',o:['40 a 60/min','60 a 80/min','100 a 120/min','Mais de 160/min'],a:2,why:'As diretrizes de suporte básico de vida recomendam compressões entre 100 e 120 por minuto, com profundidade e retorno torácico adequados.'},
    {id:'q14',subject:'Clínica Médica',q:'Em um paciente com cetoacidose diabética, a concentração sérica inicial de potássio pode estar elevada apesar de:',o:['Excesso universal de potássio corporal total','Depleção de potássio corporal total','Ausência de alterações eletrolíticas','Retenção obrigatória de potássio no tecido ósseo'],a:1,why:'Na cetoacidose diabética, perdas urinárias podem causar depleção corporal total de potássio, mesmo com potássio sérico inicialmente normal ou elevado.'},
    {id:'q15',subject:'Farmacologia',q:'Qual efeito adverso está classicamente associado aos inibidores da ECA e é menos comum com os BRA?',o:['Tosse seca','Ototoxicidade','Hiperpigmentação irreversível','Hipoglicemia direta em todos os pacientes'],a:0,why:'A inibição da degradação de bradicinina pelo IECA pode provocar tosse seca. Os BRA causam tosse com menor frequência.'},
    {id:'q16',subject:'Medicina Preventiva',q:'Para avaliar se um novo teste diagnóstico identifica pessoas com doença, qual propriedade expressa a proporção de verdadeiros positivos entre os doentes?',o:['Especificidade','Sensibilidade','Valor preditivo negativo','Prevalência'],a:1,why:'Sensibilidade = verdadeiros positivos / (verdadeiros positivos + falsos negativos), entre os indivíduos que realmente têm a doença.'}
    ,{id:'q17',subject:'Cardiologia',q:'Um eletrocardiograma mostra supradesnivelamento do segmento ST predominantemente nas derivações DI e aVL. Qual parede do miocárdio é mais diretamente representada?',o:['Inferior','Septal','Lateral alta','Posterior isolada'],a:2,why:'As derivações DI e aVL avaliam a parede lateral alta. A interpretação de isquemia exige integração com sintomas e demais derivações.'}
    ,{id:'q18',subject:'Cardiologia',q:'Qual é a alteração eletrocardiográfica mais característica da hipercalemia, especialmente em suas manifestações iniciais?',o:['Ondas T apiculadas','Intervalo QT sempre prolongado','Ondas U proeminentes','Supressão completa da onda P em todos os casos'],a:0,why:'Ondas T altas e apiculadas são achado clássico, embora o ECG possa ser normal mesmo com hipercalemia importante e outras alterações possam surgir na progressão.'}
    ,{id:'q19',subject:'Clínica Médica',q:'Em um paciente com dispneia recorrente, sibilância e suspeita de asma, qual achado funcional favorece o diagnóstico?',o:['Obstrução fixa sem qualquer variabilidade como critério obrigatório','Variabilidade da limitação ao fluxo expiratório, demonstrada por teste adequado','Capacidade vital sempre aumentada','Radiografia com infiltrado lobar em todos os casos'],a:1,why:'Asma associa sintomas respiratórios variáveis a limitação variável do fluxo expiratório, documentável por espirometria com reversibilidade ou outros testes quando indicados.'}
    ,{id:'q20',subject:'Clínica Médica',q:'Qual resultado espirométrico caracteriza um padrão ventilatório obstrutivo?',o:['Relação VEF1/CVF reduzida em relação ao limite de referência','Hemoglobina reduzida','Aumento isolado da capacidade de difusão','Saturação de oxigênio sempre normal'],a:0,why:'A diminuição da relação VEF1/CVF demonstra obstrução ao fluxo aéreo; interpretação depende de valores de referência, qualidade do exame e contexto clínico.'}
    ,{id:'q21',subject:'Clínica Médica',q:'Na análise de líquido ascítico, qual contagem de neutrófilos polimorfonucleares estabelece o critério citológico para peritonite bacteriana espontânea?',o:['Igual ou superior a 50/mm³','Igual ou superior a 100/mm³','Igual ou superior a 250/mm³','Igual ou superior a 2.500/mm³'],a:2,why:'Uma contagem de polimorfonucleares ≥250 células/mm³ no líquido ascítico é critério diagnóstico de PBE no contexto apropriado, mesmo antes do resultado da cultura.'}
    ,{id:'q22',subject:'Clínica Médica',q:'Em pessoa com cirrose, qual situação é reconhecida como possível fator precipitante de encefalopatia hepática?',o:['Hemorragia digestiva','Vacinação de rotina','Ingestão de água dentro do habitual','Ausência de qualquer doença associada'],a:0,why:'Hemorragia digestiva, constipação, infecção e distúrbios hidroeletrolíticos são exemplos de precipitantes que devem ser investigados.'}
    ,{id:'q23',subject:'Clínica Médica',q:'Qual mecanismo contribui diretamente para o desenvolvimento de hipertensão portal na cirrose?',o:['Redução da resistência vascular intra-hepática','Aumento da resistência ao fluxo portal por fibrose e alteração arquitetural','Desaparecimento do fluxo na artéria hepática em todos os casos','Diminuição universal do volume sanguíneo esplâncnico'],a:1,why:'A fibrose e os nódulos regenerativos, associados à disfunção endotelial e alterações vasculares, aumentam a resistência intra-hepática e contribuem para hipertensão portal.'}
    ,{id:'q24',subject:'Clínica Médica',q:'Qual perfil laboratorial favorece anemia ferropriva em um adulto sem contexto inflamatório importante?',o:['Ferritina sérica reduzida','Vitamina B12 elevada','Reticulocitose obrigatória','VCM elevado como achado característico'],a:0,why:'Ferritina baixa sugere reservas de ferro reduzidas. Na presença de inflamação, a ferritina pode se elevar e requer interpretação conjunta com outros parâmetros.'}
    ,{id:'q25',subject:'Clínica Médica',q:'Uma deficiência de vitamina B12 pode causar anemia macrocítica acompanhada de qual manifestação extra-hematológica?',o:['Neuropatia periférica','Proteinúria nefrótica obrigatória','Hiperreflexia fotomotora isolada como achado universal','Hemoptise como manifestação predominante'],a:0,why:'A deficiência de B12 pode provocar alterações neurológicas, inclusive parestesias e comprometimento da sensibilidade proprioceptiva, além de alterações hematológicas.'}
    ,{id:'q26',subject:'Clínica Médica',q:'Qual achado compõe a definição clínica da síndrome nefrótica?',o:['Proteinúria importante associada a hipoalbuminemia','Leucocitúria isolada','Elevação obrigatória da troponina','Glicosúria isolada sem proteinúria'],a:0,why:'A síndrome nefrótica caracteriza-se por proteinúria intensa, hipoalbuminemia e frequentemente edema e dislipidemia, com avaliação etiológica conforme o contexto.'}
    ,{id:'q27',subject:'Cirurgia Geral',q:'Em relação aos vasos epigástricos inferiores, uma hérnia inguinal indireta emerge tipicamente:',o:['Medialmente','Lateralmente','Posteriormente à veia cava','Dentro do hiato esofágico'],a:1,why:'A hérnia inguinal indireta passa pelo anel inguinal profundo, lateralmente aos vasos epigástricos inferiores; a direta costuma ocorrer medialmente.'}
    ,{id:'q28',subject:'Cirurgia Geral',q:'Qual estrutura anatômica forma o limite medial do triângulo de Hesselbach?',o:['Borda lateral do músculo reto abdominal','Ligamento inguinal','Vasos epigástricos inferiores','Artéria femoral'],a:0,why:'O triângulo de Hesselbach é limitado pela borda lateral do reto abdominal, vasos epigástricos inferiores e ligamento inguinal.'}
    ,{id:'q29',subject:'Cirurgia Geral',q:'O sinal do psoas pode ser positivo em alguns casos de apendicite, sobretudo quando o apêndice se encontra em posição:',o:['Retrocecal','Subdiafragmática esquerda','Intratorácica','Intraventricular'],a:0,why:'A irritação do músculo psoas por processo inflamatório apendicular pode provocar dor à mobilização do quadril, especialmente na posição retrocecal.'}
    ,{id:'q30',subject:'Cirurgia Geral',q:'Qual exame laboratorial é particularmente útil quando se suspeita de pancreatite aguda?',o:['Lipase sérica','Troponina exclusivamente','Cálcio urinário isolado','Hemoglobina glicada como único critério'],a:0,why:'A lipase sérica elevada, frequentemente ≥3 vezes o limite superior da normalidade, é um dos critérios diagnósticos de pancreatite aguda quando integrado à clínica e/ou imagem.'}
    ,{id:'q31',subject:'Pediatria',q:'Uma criança pequena com sibilância após quadro viral, suspeita de bronquiolite, sem sinais de infecção bacteriana, geralmente deve receber prioritariamente:',o:['Antibiótico de amplo espectro em todos os casos','Cuidados de suporte com avaliação de hidratação e oxigenação','Corticoide sistêmico obrigatório para todas as crianças','Cirurgia imediata'],a:1,why:'A bronquiolite costuma ser manejada com cuidados de suporte, incluindo manutenção da hidratação e oxigenação quando necessárias; tratamentos adicionais dependem da avaliação clínica.'}
    ,{id:'q32',subject:'Pediatria',q:'Na suspeita de meningite bacteriana, qual padrão de líquido cefalorraquidiano costuma ser encontrado?',o:['Predomínio de neutrófilos, proteína elevada e glicose reduzida','Apenas hemácias, sem leucócitos','Ausência de alteração celular em todos os casos','Glicose sempre elevada com proteína baixa'],a:0,why:'Meningite bacteriana frequentemente cursa com pleocitose neutrofílica, hiperproteinorraquia e hipoglicorraquia, embora o padrão possa variar.'}
    ,{id:'q33',subject:'Ginecologia e Obstetrícia',q:'Uma gestante no terceiro trimestre apresenta sangramento vaginal vermelho vivo, indolor, sem contrações importantes. Qual hipótese deve ser considerada?',o:['Placenta prévia','Torção testicular','Hiperêmese gravídica','Vaginose bacteriana como causa única'],a:0,why:'A placenta prévia pode se manifestar com sangramento indolor na segunda metade da gestação. O diagnóstico requer avaliação obstétrica e imagem; o toque vaginal digital deve ser evitado até exclusão.'}
    ,{id:'q34',subject:'Medicina Preventiva',q:'Qual medida de associação é clássica em estudos do tipo caso-controle?',o:['Odds ratio (razão de chances)','Risco absoluto calculado diretamente em todos os desenhos','Taxa de incidência populacional obrigatória','Média aritmética como medida de associação'],a:0,why:'Estudos caso-controle costumam utilizar a razão de chances para comparar exposição entre casos e controles, com cuidados de interpretação causal.'}
    ,{id:'q35',subject:'Medicina Preventiva',q:'Quando um teste apresenta alta sensibilidade, isso significa que:',o:['Apresenta poucos falsos negativos entre os doentes','Sempre possui especificidade de 100%','Todos os resultados positivos confirmam a doença','Seu resultado independe do ponto de corte'],a:0,why:'Sensibilidade representa a fração de doentes com teste positivo; um teste sensível tende a deixar menos doentes com resultado falso-negativo.'}
    ,{id:'q36',subject:'Farmacologia',q:'Qual grupo farmacológico pode provocar tosse seca por favorecer o acúmulo de bradicinina?',o:['Antagonistas H2','Inibidores da enzima conversora de angiotensina','Antiácidos não absorvíveis','Antagonistas dos receptores de leucotrienos'],a:1,why:'IECA reduzem a degradação de bradicinina, podendo provocar tosse seca; antagonistas do receptor AT1 têm menor incidência desse efeito.'}
    ,{id:'q37',subject:'Patologia',q:'Um infarto pálido (branco) ocorre mais frequentemente em qual órgão com circulação terminal?',o:['Rim','Pulmão com dupla irrigação','Intestino com circulação colateral abundante','Baço após congestão intensa como regra universal'],a:0,why:'Órgãos compactos com suprimento arterial terminal, como rim e coração, frequentemente apresentam infartos pálidos; o padrão depende também da reperfusão.'}
    ,{id:'q38',subject:'Patologia',q:'A necrose caseosa é classicamente associada a qual condição?',o:['Tuberculose granulomatosa','Infarto agudo do miocárdio típico','Trauma muscular com rabdomiólise isolada','Edema hidrostático isolado'],a:0,why:'Necrose caseosa é frequente em granulomas de tuberculose, mas o diagnóstico requer correlação clínica, microbiológica e histopatológica.'}
    ,{id:'q39',subject:'Diagnóstico por Imagem',q:'Na avaliação inicial de possível acidente vascular cerebral agudo, qual é um objetivo importante da tomografia de crânio sem contraste?',o:['Excluir hemorragia intracraniana visível','Confirmar todas as etiologias isquêmicas muito precocemente','Medir diretamente a concentração sérica de sódio','Substituir permanentemente o exame neurológico'],a:0,why:'A tomografia sem contraste é amplamente usada para identificar hemorragia intracraniana e orientar a avaliação urgente; infarto isquêmico precoce pode não ser evidente.'}
    ,{id:'q40',subject:'Clínica Médica',q:'Para pacientes com suspeita de tuberculose pulmonar transmissível em unidade de saúde, qual precaução respiratória é a mais apropriada?',o:['Precauções por aerossóis','Apenas precauções para gotículas em todas as circunstâncias','Somente precauções de contato com luvas','Nenhuma precaução respiratória'],a:0,why:'Tuberculose pulmonar potencialmente transmissível requer precauções por aerossóis e medidas ambientais de prevenção, conforme protocolos locais.'}
  ];
  const cardsDefault = [
    ['Qual a faixa habitual do intervalo PR no ECG de adultos?','120 a 200 ms.','Cardiologia'],
    ['Como reconhecer o sinal de Blumberg?','Dor à descompressão brusca na palpação abdominal, sugerindo irritação peritoneal.','Cirurgia Geral'],
    ['Qual é o mecanismo renal da queda da TFG com IECA/BRA em estenose bilateral?','Dilatação da arteríola eferente e diminuição da pressão de filtração glomerular.','Farmacologia'],
    ['Qual o ponto de corte do GASA que sugere hipertensão portal?','GASA ≥ 1,1 g/dL.','Clínica Médica'],
    ['Qual o intervalo recomendado das compressões torácicas na RCP adulta?','100 a 120 compressões por minuto.','Cardiologia'],
    ['Qual a diferença entre incidência e prevalência?','Incidência: casos novos em determinado período; prevalência: casos existentes em uma população.','Medicina Preventiva'],
    ['O que o sinal de Murphy sugere no contexto clínico apropriado?','Colecistite aguda: interrupção inspiratória por dor à palpação do hipocôndrio direito.','Cirurgia Geral'],
    ['O que um TSH baixo pode indicar na investigação de um nódulo tireoidiano?','Possibilidade de autonomia funcional; pode justificar cintilografia, conforme contexto clínico.','Clínica Médica']
  ];
  const nowISO = () => { const d=new Date(); return localISO(d); };
  function localISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function plusDays(iso,days){ const [y,m,d]=iso.split('-').map(Number);const dt=new Date(y,m-1,d+days);return localISO(dt); }
  function weekStart(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return localISO(d);}
  function niceDate(iso){ if(!iso)return 'Sem data';const [y,m,d]=iso.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(y,m-1,d)); }
  const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid=()=> typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`med_${Date.now()}_${Math.random().toString(36).slice(2,9)}`;
  function seed(){let today=nowISO();return {version:2, notes:{},milestones:[], profile:{name:'Estudante',period:'1º período',track:'Residência médica',weeklyMinutes:480,weeklyQuestions:60},subjects:subjectsDefault.slice(), tasks:[{id:uid(),title:'Revisar farmacologia cardiovascular',subject:'Farmacologia',minutes:40,date:today,done:false,completedAt:null},{id:uid(),title:'Resolver 15 questões de Clínica Médica',subject:'Clínica Médica',minutes:45,date:plusDays(today,1),done:false,completedAt:null},{id:uid(),title:'Revisar anatomia abdominal',subject:'Anatomia',minutes:50,date:plusDays(today,2),done:false,completedAt:null}],cards:cardsDefault.map(([front,back,subject])=>({id:uid(),front,back,subject,due:today,interval:0,reps:0})),questions:questionsDefault.map(q=>({...q,custom:false})),answers:[],sessions:[],reviews:[],createdAt:new Date().toISOString()};}
  function valid(s){return s&&[1,2].includes(s.version)&&s.profile&&Array.isArray(s.subjects)&&Array.isArray(s.tasks)&&Array.isArray(s.cards)&&Array.isArray(s.questions)&&Array.isArray(s.answers)&&Array.isArray(s.sessions)&&Array.isArray(s.reviews);}
  function load(){try{let s=JSON.parse(localStorage.getItem(KEY));if(valid(s)){const existingIds=new Set(s.questions.map(q=>q.id));const newQuestions=questionsDefault.filter(q=>!existingIds.has(q.id));return {...s,version:2,questions:[...s.questions,...newQuestions],notes:s.notes&&typeof s.notes==='object'&&!Array.isArray(s.notes)?s.notes:{},milestones:Array.isArray(s.milestones)?s.milestones:[]};}}catch{}return seed();}
  let state=load(),view='dashboard',taskFilter='all',cardFilter='due',quizSubject='Todas',currentQuiz=null,flashFlip=false,selectedCard=null,toastHandle=null,errorSubject='Todas';
  let timerDuration=25,timerRemaining=25*60,timerUntil=null,timerInterval=null;
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Armazenamento indisponível. Faça um backup dos dados.');} window.MedAtlasCloud.onSave(state);};
  const $=(id)=>document.getElementById(id);
  // A inicialização não gera alteração remota; somente ações do usuário sincronizam.
  function toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>t.classList.remove('show'),3100);}
  function navRender(){
    $('side-nav').innerHTML=nav.map(([id,icon,title])=>`<button type="button" class="nav-link ${id===view?'active':''}" data-nav="${id}" aria-current="${id===view?'page':'false'}"><span class="nav-icon">${icon}</span>${esc(title)}</button>`).join('');
    const mobile=[['dashboard','⌂','Início'],['community','♧','Comunidade'],['+','＋','Novo'],['cards','▤','Revisões'],['profile','◉','Perfil']];
    $('bottom-nav').innerHTML=mobile.map(([id,icon,title])=>id==='+'?`<button type="button" class="bottom-link bottom-add" data-action="task-add" aria-label="Criar nova tarefa"><span class="nav-icon">${icon}</span>${title}</button>`:`<button type="button" class="bottom-link ${id===view?'active':''}" data-nav="${id}" aria-current="${id===view?'page':'false'}"><span class="nav-icon">${icon}</span>${title}</button>`).join('');
  }
  function pageHeader(tag,title,desc,right=''){return `<div class="page-header"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`;}
  const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-header"><h2>${title}</h2>${extra}</div>${body}</section>`;
  const progressBar=(n,total,blue=false)=>`<div class="progress-track"><div class="progress-fill ${blue?'blue':''}" style="width:${Math.min(100,Math.max(0,total?100*n/total:0))}%"></div></div>`;
  const thisWeek = iso=>iso&&iso>=weekStart()&&iso<=plusDays(weekStart(),6);
  function weekly(){let sessions=state.sessions.filter(x=>thisWeek(x.date)),answers=state.answers.filter(x=>thisWeek(x.date)),tasks=state.tasks.filter(x=>thisWeek(x.completedAt)),reviews=state.reviews.filter(x=>thisWeek(x.date));return {minutes:sessions.reduce((a,s)=>a+Number(s.minutes||0),0),questions:answers.length,correct:answers.filter(a=>a.correct).length,tasks:tasks.length,reviews:reviews.length};}
  function dueCards(){return state.cards.filter(c=>c.due<=nowISO()).sort((a,b)=>a.due.localeCompare(b.due));}
  function pendingTasks(){return state.tasks.filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date));}
  function taskHTML(t){return `<div class="task-row"><button type="button" class="task-check ${t.done?'done':''}" data-action="task-toggle" data-id="${esc(t.id)}" title="${t.done?'Reabrir tarefa':'Concluir tarefa'}" aria-label="${t.done?'Reabrir':'Concluir'} ${esc(t.title)}">${t.done?'✓':''}</button><div class="task-content"><div class="task-title ${t.done?'done':''}">${esc(t.title)}</div><div class="task-meta">${esc(t.subject)} · ${esc(niceDate(t.date))} · ${Number(t.minutes)||0} min ${!t.done&&t.date<nowISO()?'<span class="pill amber">Atrasada</span>':''}</div></div><div class="mini-actions"><button type="button" class="action-mini" data-action="task-edit" data-id="${esc(t.id)}" aria-label="Editar tarefa">✎</button><button type="button" class="action-mini" data-action="task-delete" data-id="${esc(t.id)}" aria-label="Excluir tarefa">×</button></div></div>`;}
  function activityDays(){const start=weekStart();return Array.from({length:7},(_,i)=>{const date=plusDays(start,i);return {date,minutes:state.sessions.filter(s=>s.date===date).reduce((a,s)=>a+Number(s.minutes||0),0)};});}
  function dashboard(){
    const w=weekly(),due=dueCards().length,tasks=pendingTasks();
    const chart=activityDays(),max=Math.max(60,...chart.map(d=>d.minutes));
    const doneTotal=state.tasks.filter(x=>x.done).length;
    const overall=state.tasks.length?Math.round(100*doneTotal/state.tasks.length):0;
    const todayDate=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
    const studyTopics=['Clínica Médica','Cirurgia Geral','Pediatria','Farmacologia'];
    const courseIcon=['♡','✧','◈','⚗'];
    return `<div class="premium-greeting"><div><span class="premium-greeting-label">${esc(todayDate)} · SUA JORNADA NA MEDICINA</span><h1>Olá, ${esc(state.profile.name||'Estudante')}<span class="greeting-wave"> ✦</span></h1><p>Pequenos passos hoje. Grandes conquistas amanhã.</p></div><button type="button" class="premium-avatar" data-nav="profile" aria-label="Abrir meu perfil">◉</button></div>
    <div class="premium-search"><span aria-hidden="true">⌕</span><span>O que vamos estudar hoje?</span><button type="button" class="btn btn-primary btn-small" data-nav="planner">Minha agenda →</button></div>
    <section class="premium-quick" aria-label="Acesso rápido">
      <button data-nav="cards" type="button" class="premium-quick-tile"><span class="premium-quick-icon">▤</span><b>Flashcards</b><small>${due} pendentes</small></button>
      <button data-nav="planner" type="button" class="premium-quick-tile"><span class="premium-quick-icon">▦</span><b>Meu plano</b><small>Organizar</small></button>
      <button data-nav="quiz" type="button" class="premium-quick-tile"><span class="premium-quick-icon">✎</span><b>Questões</b><small>Praticar</small></button>
      <button data-nav="community" type="button" class="premium-quick-tile"><span class="premium-quick-icon">♧</span><b>Comunidade</b><small>Compartilhar</small></button>
    </section>
    <div class="premium-main-grid"><div class="premium-stack">
      <section class="premium-progress"><div class="premium-card-heading"><div><span class="premium-kicker">SEU DESENVOLVIMENTO</span><h2>Progresso nos estudos</h2></div><button class="premium-text-button" type="button" data-nav="progress">Ver relatório ↗</button></div>
        <div class="premium-progress-body"><div class="premium-ring" style="--percent:${overall}"><span><b>${overall}%</b><small>tarefas</small></span></div>
          <div class="premium-progress-message"><b>Você está evoluindo!</b><p>${doneTotal} de ${state.tasks.length} tarefas concluídas no total.</p><div class="premium-progress-metrics"><span><b>${w.questions}</b> questões esta semana</span><span><b>${(w.minutes/60).toLocaleString('pt-BR',{maximumFractionDigits:1})}h</b> de estudo</span></div></div></div>
        <div class="premium-chart"><div class="premium-chart-heading">ATIVIDADE DA SEMANA</div><div class="bar-chart">${chart.map(d=>`<div class="bar-col"><div class="bar-outer"><div class="bar ${d.date===nowISO()?'today':''}" style="height:${Math.max(4,d.minutes/max*64)}px" title="${d.minutes} min"></div></div><div class="bar-label">${new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(new Date(d.date+'T12:00:00')).replace('.','')}</div></div>`).join('')}</div></div>
      </section>
      <section class="premium-panel premium-tasks"><div class="premium-card-heading"><div><span class="premium-kicker">ORGANIZE SUA ROTINA</span><h2>Próximas atividades</h2></div><button class="premium-text-button" type="button" data-nav="planner">Ver todas →</button></div>
        ${tasks.length?tasks.slice(0,4).map(taskHTML).join(''):`<div class="empty"><div class="empty-icon">✓</div><strong>Seu planejamento está em dia!</strong><span>Crie uma nova tarefa para começar.</span></div>`}
        <button type="button" class="premium-add-task" data-action="task-add">＋ Criar nova atividade</button>
      </section>
      <section class="premium-panel"><div class="premium-card-heading"><div><span class="premium-kicker">ESCOLHA SEU CAMINHO</span><h2>Explore suas áreas</h2></div><button class="premium-text-button" data-nav="quiz" type="button">Mais questões →</button></div><div class="premium-specialties">${studyTopics.map((x,i)=>`<button type="button" data-nav="quiz" class="premium-specialty"><span>${courseIcon[i]}</span><b>${x}</b></button>`).join('')}</div></section>
    </div><div class="premium-stack">
      <section class="premium-hero"><span class="premium-hero-eyebrow">ESTUDNEXA • CONECTE-SE</span><h2>Mais que estudar.<br><em>Crescer juntos.</em></h2><p>Compartilhe conhecimento e encontre estudantes que vivem a mesma jornada.</p><button class="premium-hero-btn" type="button" data-nav="community">Explorar comunidade ↗</button><span class="premium-hero-ornament" aria-hidden="true">✧</span></section>
      <section class="premium-panel premium-overview"><div class="premium-card-heading"><h2>Suas metas semanais</h2><button type="button" class="premium-text-button" data-action="settings">Ajustar ↗</button></div><div class="progress-row"><div class="progress-info"><span>Tempo de estudo</span><span>${w.minutes}/${state.profile.weeklyMinutes} min</span></div>${progressBar(w.minutes,state.profile.weeklyMinutes)}</div><div class="progress-row"><div class="progress-info"><span>Questões</span><span>${w.questions}/${state.profile.weeklyQuestions}</span></div>${progressBar(w.questions,state.profile.weeklyQuestions,true)}</div></section>
      <section class="premium-panel"><div class="premium-card-heading"><h2>Momento de foco</h2></div>${timerHTML()}</section>
      <section class="premium-panel premium-side-link"><div class="premium-card-heading"><h2>Seu caderno de erros</h2></div><p>Revise as questões em que você mais precisa evoluir.</p><button type="button" class="btn btn-outline" data-nav="errors">Abrir caderno →</button></section>
    </div></div>`;
  }
  function stat(label,num,em,sub){return `<div class="stat-card"><div class="stat-label">${label}<span class="stat-emoji">${em}</span></div><div class="stat-num">${num}</div><div class="stat-sub">${sub}</div></div>`;}
  function timerHTML(){return `<div class="timer-panel"><div class="tab-row" style="justify-content:center"><button data-action="timer-mode" data-value="25" class="tab ${timerDuration===25?'active':''}">25 min</button><button data-action="timer-mode" data-value="50" class="tab ${timerDuration===50?'active':''}">50 min</button><button data-action="timer-mode" data-value="15" class="tab ${timerDuration===15?'active':''}">15 min</button></div><div class="timer" id="timer-display">${fmtTime(timerRemaining)}</div><div class="timer-controls"><button class="btn btn-primary" data-action="timer-toggle">${timerUntil?'Pausar':'▶ Iniciar'}</button><button class="btn btn-outline" data-action="timer-reset">↻ Reiniciar</button></div><p class="note">As sessões concluídas entram na sua meta semanal. Mantenha esta página aberta durante o foco.</p><button class="btn-quiet" data-action="manual-log">＋ Registrar estudo manualmente</button></div>`;}
  function fmtTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
  function planner(){let tasks=state.tasks.slice().sort((a,b)=>(a.done-b.done)||a.date.localeCompare(b.date));if(taskFilter==='pending')tasks=tasks.filter(x=>!x.done);if(taskFilter==='done')tasks=tasks.filter(x=>x.done);if(taskFilter==='today')tasks=tasks.filter(x=>x.date===nowISO());let w=weekly();return `${pageHeader('ORGANIZAÇÃO E CONSISTÊNCIA','Meu planejamento','Defina prioridades e transforme objetivos em pequenos passos.','<button class="btn btn-primary" data-action="task-add">＋ Adicionar tarefa</button>')}
    <div class="stats-grid">${stat('Tarefas totais',state.tasks.length,'▦','No seu planejamento')}${stat('Concluídas',state.tasks.filter(x=>x.done).length,'✓','Desde o início')}${stat('Previstas hoje',state.tasks.filter(x=>x.date===nowISO()).length,'◷','Atividades de hoje')}${stat('Estudo na semana',`${w.minutes} min`,'⏱','Tempo registrado')}</div>
    <div class="grid-main"><div class="stack">${panel('Minha lista de estudos',`<div class="tab-row">${[['all','Todas'],['pending','Pendentes'],['today','Hoje'],['done','Concluídas']].map(([id,n])=>`<button class="tab ${taskFilter===id?'active':''}" data-action="task-filter" data-value="${id}">${n}</button>`).join('')}</div>${tasks.length?tasks.map(taskHTML).join(''):`<div class="empty"><div class="empty-icon">▦</div><strong>Nenhuma tarefa nesta visão</strong><span>Experimente outro filtro ou adicione uma tarefa.</span></div>`}`)}
      </div><div class="stack">${panel('Planejamento de 7 dias',`<p class="subtle">Minutos planejados para cada dia, considerando tarefas ainda não concluídas.</p><div class="week-grid">${Array.from({length:7},(_,i)=>{let date=plusDays(weekStart(),i);let mins=state.tasks.filter(t=>!t.done&&t.date===date).reduce((n,t)=>n+Number(t.minutes||0),0);return `<div class="day-box ${date===nowISO()?'today':''}"><b>${'SMTQQSS'[i]}</b><div class="day-time">${mins}m</div><span>${date.slice(8)}</span></div>`;}).join('')}</div>`)}${panel('Estratégia sugerida',`<p>Combine revisão teórica, resolução de questões e repetição espaçada.</p><div class="helper-tip"><strong>Para quem mira a residência:</strong> mantenha um contato semanal com Clínica Médica, Cirurgia Geral, Pediatria, Ginecologia/Obstetrícia e Medicina Preventiva, adaptado à fase do curso.</div>`)}</div></div>`;}
  function cards(){let due=dueCards();let list=cardFilter==='due'?due:state.cards.slice();if(!selectedCard||!list.some(x=>x.id===selectedCard)){selectedCard=list[0]?.id||null;flashFlip=false;}let current=list.find(c=>c.id===selectedCard);return `${pageHeader('MEMORIZAÇÃO ATIVA','Revisão espaçada','Recorde, confira e avalie sua lembrança para organizar as próximas revisões.','<button class="btn btn-primary" data-action="card-add">＋ Novo flashcard</button>')}
  <div class="stats-grid">${stat('Cartões no baralho',state.cards.length,'▤','Inclui cartões personalizados')}${stat('Para revisar hoje',due.length,'◷','Com revisão programada')}${stat('Revisões na semana',weekly().reviews,'✓','Total de respostas')}${stat('Revisados alguma vez',state.cards.filter(c=>c.reps>0).length,'◎','Cartões com histórico')}</div>
  <div class="flash-wrap"><div class="stack">${panel('Hora de praticar',`<div class="tab-row"><button class="tab ${cardFilter==='due'?'active':''}" data-action="card-filter" data-value="due">Devidos hoje (${due.length})</button><button class="tab ${cardFilter==='all'?'active':''}" data-action="card-filter" data-value="all">Todos (${state.cards.length})</button></div>${current?`<div class="flash-card ${flashFlip?'flipped':''}"><div class="overline">${esc(current.subject)} · ${flashFlip?'RESPOSTA':'PERGUNTA'}</div><h2>${esc(flashFlip?current.back:current.front)}</h2><p>${flashFlip?'Como foi sua lembrança?':'Tente responder antes de revelar.'}</p></div>${!flashFlip?`<div class="flash-controls"><button class="btn btn-primary" data-action="card-reveal">Mostrar resposta</button></div>`:`<div class="flash-controls"><button class="btn btn-outline" data-action="card-grade" data-value="again">Repetir</button><button class="btn btn-outline" data-action="card-grade" data-value="hard">Difícil</button><button class="btn btn-primary" data-action="card-grade" data-value="good">Lembrei</button><button class="btn btn-primary" data-action="card-grade" data-value="easy">Fácil</button></div>`}`:`<div class="empty"><div class="empty-icon">🎉</div><strong>Revisões em dia!</strong><span>Volte amanhã ou selecione “Todos”.</span></div>`}`)}
   </div><div class="stack">${panel('Seu baralho',`<div class="tasks-list" style="max-height:540px;overflow:auto">${state.cards.length?state.cards.slice().sort((a,b)=>a.due.localeCompare(b.due)).map(c=>`<div class="deck-item"><div class="deck-label"><b>${esc(c.front)}</b><small>${esc(c.subject)} · ${c.due<=nowISO()?'Revisar agora':`Próxima: ${niceDate(c.due)}`}</small></div><button class="action-mini" data-action="card-select" data-id="${esc(c.id)}" title="Abrir cartão">↗</button><button class="action-mini" data-action="card-delete" data-id="${esc(c.id)}" title="Excluir cartão">×</button></div>`).join(''):`<div class="empty">Crie seu primeiro cartão!</div>`}</div>`)}<div class="callout"><strong>Como funciona?</strong>Seu intervalo aumenta quando você lembra. Se errar, o cartão volta à revisão do dia seguinte. O método é simplificado e pode ser ajustado nas próximas versões.</div></div></div>`;}
  function getQuestionSubjects(){return ['Todas',...new Set(state.questions.map(x=>x.subject))].sort((a,b)=>a==='Todas'?-1:b==='Todas'?1:a.localeCompare(b));}
  function quiz(){let w=weekly();if(!currentQuiz){return `${pageHeader('APRENDIZAGEM POR QUESTÕES','Banco de questões','Questões autorais e comentadas para praticar raciocínio clínico e revisão.','<button class="btn btn-outline" data-action="question-add">＋ Criar questão</button>')}
   <div class="quiz-layout"><div class="stack">${panel('Iniciar simulado',`<div class="field"><label for="quiz-subject">Escolha a área de estudo</label><select id="quiz-subject">${getQuestionSubjects().map(s=>`<option value="${esc(s)}" ${s===quizSubject?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="helper-tip">O simulado sorteia até 10 questões do tema escolhido. Ao responder, você recebe explicação e registra o resultado no painel.</div><div class="form-actions"><button class="btn btn-primary" data-action="quiz-start">Iniciar simulado →</button></div>`)}</div><div class="stack">${panel('Seu desempenho',`<div class="quiz-stats"><div><b>${w.questions}</b><small>Questões na semana</small></div><div><b>${w.questions?Math.round(w.correct/w.questions*100)+'%':'—'}</b><small>Aproveitamento semanal</small></div></div><p class="note">${state.questions.length} questões no banco atual. Adicione questões próprias para expandir o conteúdo.</p>`)}${panel('Sugestão de estudo',`<p>Resolva questões por especialidade e revise os erros no mesmo dia. Faça revisões mistas para aproximar a prática de provas de residência.</p>`)}</div></div>`;}
   if(currentQuiz.index>=currentQuiz.ids.length){const n=currentQuiz.ids.length,correct=currentQuiz.correct,pct=n?Math.round(correct/n*100):0;return `${pageHeader('RESULTADO DO SIMULADO','Simulado concluído','Confira seu desempenho e escolha o próximo tema.')}${panel('Seu resultado',`<div class="result-ring" style="--percent:${pct}%"><span>${pct}%</span></div><div style="text-align:center"><h2>${correct} de ${n} questões corretas</h2><p class="muted">Os resultados já foram salvos no seu histórico de estudos.</p></div><div class="form-actions"><button class="btn btn-outline" data-action="quiz-finish">Voltar ao banco</button><button class="btn btn-primary" data-action="quiz-restart">Novo simulado →</button></div>`)}`;}
   const q=state.questions.find(x=>x.id===currentQuiz.ids[currentQuiz.index]);if(!q){currentQuiz=null;return quiz();}let picked=currentQuiz.picked;return `${pageHeader('SIMULADO EM ANDAMENTO',`Questão ${currentQuiz.index+1} de ${currentQuiz.ids.length}`,'Leia com atenção e selecione a melhor alternativa.','<button class="btn btn-outline btn-small" data-action="quiz-quit">Encerrar</button>')}
   <div class="quiz-layout"><div class="stack">${panel(`Questão ${currentQuiz.index+1}`,`<div class="quiz-number">${esc(q.subject)}</div><h2 class="quiz-question">${esc(q.q)}</h2>${q.o.map((opt,i)=>`<button class="option ${picked!==null?'answered':''} ${picked!==null&&i===q.a?'correct':''} ${picked===i&&picked!==q.a?'wrong':''}" data-action="quiz-answer" data-value="${i}" ${picked!==null?'disabled':''}><span class="opt-letter">${'ABCD'[i]}</span><span>${esc(opt)}</span></button>`).join('')}${picked!==null?`<div class="feedback ${picked===q.a?'':'wrong'}"><strong>${picked===q.a?'✓ Resposta correta':'✕ Resposta incorreta'}</strong><p><b>Gabarito: ${'ABCD'[q.a]}.</b> ${esc(q.why)}</p></div><div class="form-actions"><button class="btn btn-primary" data-action="quiz-next">${currentQuiz.index+1===currentQuiz.ids.length?'Ver resultado':'Próxima questão →'}</button></div>`:''}`)}</div>
   <div class="stack">${panel('Progresso do simulado',`<div class="progress-info"><span>Respondidas</span><span>${currentQuiz.index+(picked!==null?1:0)} / ${currentQuiz.ids.length}</span></div>${progressBar(currentQuiz.index+(picked!==null?1:0),currentQuiz.ids.length)}<div class="quiz-stats top-gap"><div><b>${currentQuiz.correct}</b><small>Acertos</small></div><div><b>${currentQuiz.index+(picked!==null?1:0)-currentQuiz.correct}</b><small>Erros</small></div></div>`)}</div></div>`;}
  const trainingStages = [
    {title:'Fundamentos',period:'1º ao 4º período',range:[1,4],description:'Construir bases consistentes para compreender as doenças e interpretar achados.',steps:[
      ['base-anat','Revisar anatomia e fisiologia por sistemas'],['base-path','Relacionar fisiopatologia e manifestações clínicas'],['base-epi','Dominar epidemiologia, testes diagnósticos e bioestatística']]},
    {title:'Ciclo clínico',period:'5º ao 8º período',range:[5,8],description:'Integrar mecanismos, semiologia, diagnóstico e raciocínio clínico.',steps:[
      ['clinic-primary','Estudar Clínica Médica com casos e questões'],['clinic-surg','Revisar Cirurgia Geral e urgências cirúrgicas'],['clinic-mother','Consolidar Pediatria e Ginecologia/Obstetrícia'],['clinic-spaced','Manter revisões espaçadas e caderno de erros']]},
    {title:'Internato',period:'9º ao 12º período',range:[9,12],description:'Associar prática supervisionada, segurança e preparação para provas.',steps:[
      ['intern-cases','Registrar aprendizados de casos sem dados de pacientes'],['intern-guide','Revisar diretrizes e protocolos oficiais vigentes'],['intern-practice','Fazer simulados por grandes áreas e provas anteriores']]},
    {title:'Reta final',period:'Pré-prova e residência',range:[13,99],description:'Direcionar os estudos para os editais, desempenho e requisitos curriculares.',steps:[
      ['res-notices','Mapear editais, documentação e critérios curriculares'],['res-tests','Fazer simulados completos com tempo controlado'],['res-errors','Priorizar temas de baixo desempenho e revisões finais']]}
  ];
  function currentTrainingStage(){const n=Number.parseInt(state.profile.period,10);return Number.isFinite(n)?Math.max(0,Math.min(3,Math.floor((n-1)/4))):3;}
  function latestQuestionAttempts(){let m=new Map();for(const a of state.answers){if(a.questionId)m.set(a.questionId,a);}return m;}
  function wrongQuestions(){const last=latestQuestionAttempts();return state.questions.filter(q=>last.get(q.id)&&!last.get(q.id).correct);}
  function weakestSubjects(){const grouped={};for(const a of state.answers){let k=a.subject;if(!k)continue;let x=grouped[k]||(grouped[k]={total:0,correct:0});x.total++;if(a.correct)x.correct++;}return Object.entries(grouped).filter(([k,v])=>v.total>=2).sort((a,b)=>a[1].correct/a[1].total-b[1].correct/b[1].total).map(([name,stat])=>({name,total:stat.total,accuracy:Math.round(stat.correct/stat.total*100)}));}
  function studyStreak(){let dates=new Set([...state.sessions.map(s=>s.date),...state.answers.map(a=>a.date),...state.reviews.map(r=>r.date)]);let date=nowISO();if(!dates.has(date))date=plusDays(date,-1);let n=0;while(dates.has(date)){n++;date=plusDays(date,-1);}return n;}
  function errors(){const all=wrongQuestions(),subjectChoices=['Todas',...new Set(all.map(q=>q.subject))];if(!subjectChoices.includes(errorSubject))errorSubject='Todas';const visible=all.filter(q=>errorSubject==='Todas'||q.subject===errorSubject);const weak=weakestSubjects();return `${pageHeader('PRÁTICA DIRECIONADA','Caderno de erros','Reforce os conceitos que ainda precisam de revisão. Uma questão sai desta lista após um novo acerto.','<button class="btn btn-primary" data-action="quiz-wrong" '+(all.length?'':'disabled')+'>↻ Revisar erros</button>')}
    <section class="stats-grid">${stat('Erros a revisar',all.length,'◈','Última tentativa incorreta')}${stat('Erros registrados',state.answers.filter(a=>!a.correct).length,'✎','Histórico de tentativas')}${stat('Áreas com dados',weak.length,'▤','Pelo menos 2 questões feitas')}${stat('Sequência de estudo',`${studyStreak()} dias`,'✦','Dias seguidos de atividade')}</section>
    <div class="grid-main"><div class="stack">${panel('Questões que merecem atenção',`<div class="field"><label for="errors-subject">Filtrar por área</label><select id="errors-subject">${subjectChoices.map(t=>`<option ${t===errorSubject?'selected':''}>${esc(t)}</option>`).join('')}</select></div>${visible.length?visible.map(q=>`<article class="error-item"><div class="error-header"><span class="pill amber">${esc(q.subject)}</span><span class="subtle">Questão ${esc(q.id)}</span></div><h3>${esc(q.q)}</h3><p><b>Resposta:</b> ${esc(q.o[q.a])}</p><p class="note">${esc(q.why)}</p>${state.notes[q.id]?`<div class="study-note">📝 ${esc(state.notes[q.id])}</div>`:''}<div class="file-buttons"><button class="btn btn-primary btn-small" data-action="quiz-one" data-id="${esc(q.id)}">Refazer questão</button><button class="btn btn-outline btn-small" data-action="error-note" data-id="${esc(q.id)}">${state.notes[q.id]?'Editar nota':'Criar nota'}</button><button class="btn btn-outline btn-small" data-action="error-card" data-id="${esc(q.id)}">Virar flashcard</button></div></article>`).join(''):`<div class="empty"><div class="empty-icon">✓</div><strong>Nenhuma questão pendente!</strong><span>Os erros aparecerão aqui conforme você realizar simulados. Revise por área em Questões.</span></div>`}`)}</div>
    <div class="stack">${panel('Áreas para priorizar',weak.length?weak.slice(0,6).map(x=>`<div class="progress-row"><div class="progress-info"><span>${esc(x.name)}</span><span>${x.accuracy}% (${x.total} respostas)</span></div>${progressBar(x.accuracy,100,x.accuracy>=70)}</div>`).join(''):'<p class="subtle">Responda pelo menos duas questões da mesma área para começar a identificar tendências.</p>')}
    <div class="callout"><strong>Aprenda com o erro</strong>Leia o comentário, anote a causa do erro e tente responder novamente sem olhar o gabarito. Os dados refletem seus registros locais.</div></div></div>`;}
  function roadmap(){const current=currentTrainingStage(),completed=new Set(state.milestones);let total=trainingStages.reduce((n,st)=>n+st.steps.length,0);return `${pageHeader('DA FACULDADE À RESIDÊNCIA','Minha trilha de formação','Uma jornada orientativa por etapas. Personalize as tarefas conforme o currículo da sua escola e os editais de interesse.','<button class="btn btn-primary" data-action="weekly-plan">✦ Montar semana</button>')}
    <div class="hero roadmap-hero"><div class="hero-content"><div class="hero-label">SEU PLANO DE LONGO PRAZO</div><h2>${esc(state.profile.period)} — ${esc(trainingStages[current].title)}</h2><p>${completed.size} de ${total} marcos concluídos · ${studyStreak()} dia(s) em sequência</p></div><div class="hero-art" aria-hidden="true">🎓</div></div>
    <div class="grid-main"><div class="stack">${trainingStages.map((st,i)=>panel(`${i+1}. ${st.title}`,`<p class="subtle">${esc(st.period)} · ${esc(st.description)}</p><div class="roadmap-list">${st.steps.map(([id,title])=>`<label class="roadmap-item"><input type="checkbox" data-milestone="${esc(id)}" ${completed.has(id)?'checked':''}/><span>${esc(title)}</span></label>`).join('')}</div>`,i===current?'<span class="pill mint">Etapa atual</span>':'')).join('')}</div><div class="stack">${panel('Plano semanal sugerido',`<p>Com um toque, o MedAtlas cria até cinco tarefas para os próximos sete dias, dando preferência às áreas com menor aproveitamento quando há respostas suficientes.</p><div class="callout"><strong>Sem inteligência artificial externa</strong>O planejamento é automático, baseado nas metas e registros salvos neste dispositivo. Você pode editar todas as tarefas.</div><div class="form-actions"><button class="btn btn-primary" data-action="weekly-plan">Gerar atividades desta semana →</button></div><p class="note">Um planejamento automático por semana. Não substitui avaliação individual de carga horária ou planejamento docente.</p>`) }
      ${panel('O que estudar agora?',`<div class="tip-list"><p><b>1.</b> Mantenha constância com tarefas curtas e mensuráveis.</p><p><b>2.</b> Priorize questões, revisões espaçadas e correção ativa dos erros.</p><p><b>3.</b> Consulte periodicamente editais oficiais das instituições onde pretende prestar residência.</p></div>`)}</div></div>`;}
  function makeWeeklyPlan(){const week=weekStart();if(state.tasks.some(t=>t.origin==='auto'&&t.planWeek===week)){toast('O plano automático desta semana já foi criado. Edite-o em Planejar.');goto('planner');return;}const weak=weakestSubjects().map(s=>s.name);const fallbacks=['Clínica Médica','Cirurgia Geral','Pediatria','Ginecologia e Obstetrícia','Medicina Preventiva'];const areas=[...new Set([...weak,...fallbacks,...state.subjects])];const mins=Math.max(25,Math.min(90,Math.round(state.profile.weeklyMinutes/5)));const templates=[['Revisar conceitos essenciais de ',0,0],['Resolver questões de ',1,1],['Revisar casos e diagnóstico de ',2,2],['Fazer revisão ativa de ',3,4],['Corrigir erros e revisar ',4,6]];for(const [title,index,day] of templates){const subject=areas[index%areas.length];state.tasks.push({id:uid(),title:title+subject,subject,minutes:mins,date:plusDays(nowISO(),day),done:false,completedAt:null,origin:'auto',planWeek:week});}save();toast('Cinco atividades adicionadas ao planejamento!');goto('planner');}
  function errorNoteForm(id){const q=state.questions.find(q=>q.id===id);if(!q)return;dialogHTML('Minha anotação de revisão',`<form id="error-note-form"><input type="hidden" name="id" value="${esc(id)}"/><div class="field"><label>Por que errei? O que preciso lembrar?</label><textarea name="note" maxlength="1200" rows="6" placeholder="Ex.: confundi sensibilidade com especificidade">${esc(state.notes[id]||'')}</textarea></div><div class="dialog-actions"><button class="btn btn-outline" type="button" data-action="dialog-close">Cancelar</button><button class="btn btn-primary" type="submit">Salvar anotação</button></div></form>`);}
  function startQuestionSubset(ids){if(!ids.length){toast('Nenhum erro pendente de revisão.');return;}currentQuiz={ids:ids.slice(0,10),index:0,correct:0,picked:null};goto('quiz');}
  function csvCell(x){let s=String(x??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
  function exportCSV(){const rows=[['Tipo','Data','Disciplina','Descrição','Minutos','Situação','Acerto']];for(const x of state.sessions)rows.push(['Estudo',x.date,x.subject,'Sessão registrada',x.minutes,'Concluído','']);for(const x of state.answers){const q=state.questions.find(q=>q.id===x.questionId);rows.push(['Questão',x.date,x.subject,q?.q||x.questionId,'',x.correct?'Correta':'Incorreta',x.correct?'1':'0']);}for(const x of state.tasks)rows.push(['Tarefa',x.completedAt||x.date,x.subject,x.title,x.minutes,x.done?'Concluída':'Pendente','']);download(`medatlas-dados-${nowISO()}.csv`,'\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Planilha CSV exportada.');}
  function report(){let w=weekly(),tasks=state.tasks.filter(x=>thisWeek(x.completedAt));let percent=w.questions?Math.round(w.correct/w.questions*100):0;let topicMap={};for(let x of state.answers.filter(x=>thisWeek(x.date))){let t=topicMap[x.subject]||(topicMap[x.subject]={total:0,correct:0});t.total++;if(x.correct)t.correct++;}let topics=Object.entries(topicMap).sort((a,b)=>b[1].total-a[1].total).map(([k,x])=>`  • ${k}: ${x.correct}/${x.total} acertos`).join('\n');return `RELATÓRIO SEMANAL — MEDATLAS\nEstudante: ${state.profile.name}\nPeríodo: ${state.profile.period}\nSemana: ${niceDate(weekStart())} a ${niceDate(plusDays(weekStart(),6))}\nObjetivo: ${state.profile.track}\n\nTEMPO DE ESTUDO: ${w.minutes} de ${state.profile.weeklyMinutes} min (${Math.round(w.minutes/state.profile.weeklyMinutes*100)||0}% da meta)\nQUESTÕES: ${w.questions} de ${state.profile.weeklyQuestions} (${w.correct} corretas; ${w.questions?percent+'%':'sem dados'} de acerto)\nFLASHCARDS REVISADOS: ${w.reviews}\nERROS PENDENTES: ${wrongQuestions().length}\nSEQUÊNCIA DE ESTUDOS: ${studyStreak()} dia(s)\nTAREFAS CONCLUÍDAS: ${tasks.length}\nREVISÕES PENDENTES HOJE: ${dueCards().length}\n\nDESEMPENHO POR ÁREA:\n${topics||'  Nenhuma questão respondida nesta semana.'}\n\nPRÓXIMAS ATIVIDADES:\n${pendingTasks().slice(0,5).map(t=>`  • ${t.title} (${niceDate(t.date)})`).join('\n')||'  Nenhuma tarefa pendente.'}\n\nGostaria de revisar meu plano semanal de estudos e priorizar áreas com dificuldade.`;}
  function progress(){let w=weekly(),days=activityDays();let totalMinutes=state.sessions.reduce((a,x)=>a+Number(x.minutes||0),0);let correct=state.answers.filter(x=>x.correct).length;return `${pageHeader('ACOMPANHAMENTO CONTÍNUO','Minha evolução','Transforme dados de estudo em decisões para a próxima semana.','<button class="btn btn-primary" data-action="report-copy">Copiar relatório ↗</button>')}
    <section class="stats-grid">${stat('Total de horas',`${(totalMinutes/60).toFixed(1).replace('.',',')}h`,'⏱','Desde que começou')}${stat('Questões respondidas',state.answers.length,'✎','Acumuladas')}${stat('Aproveitamento total',state.answers.length?`${Math.round(correct/state.answers.length*100)}%`:'—','◎','Taxa de acertos')}${stat('Tarefas concluídas',state.tasks.filter(x=>x.done).length,'✓','Acumuladas')}</section>
    <div class="grid-main"><div class="stack">${panel('Fechamento da semana',`<div class="progress-row"><div class="progress-info"><span>Tempo de estudo</span><span>${w.minutes}/${state.profile.weeklyMinutes} minutos</span></div>${progressBar(w.minutes,state.profile.weeklyMinutes)}</div><div class="progress-row"><div class="progress-info"><span>Resolução de questões</span><span>${w.questions}/${state.profile.weeklyQuestions}</span></div>${progressBar(w.questions,state.profile.weeklyQuestions,true)}</div><div class="progress-row"><div class="progress-info"><span>Revisões de flashcards</span><span>${w.reviews} realizadas</span></div>${progressBar(w.reviews,Math.max(1,w.reviews+dueCards().length))}</div><div class="week-grid">${days.map(d=>`<div class="day-box ${d.date===nowISO()?'today':''}"><b>${'SMTQQSS'[days.indexOf(d)]}</b><div class="day-time">${d.minutes}m</div><span>${d.date.slice(8)}</span></div>`).join('')}</div>`) }
     ${panel('Relatório para acompanhamento',`<p class="subtle">Copie e envie este resumo na conversa com o ChatGPT. Assim, você pode receber ajustes semanais individualizados.</p><div class="weekly-summary" id="weekly-report">${esc(report())}</div><div class="file-buttons top-gap"><button class="btn btn-primary btn-small" data-action="report-copy">Copiar resumo</button><button class="btn btn-outline btn-small" data-action="report-download">Baixar .txt</button></div>`)}
    </div><div class="stack">${panel('Sua rotina de foco',timerHTML())}${panel('Backup e privacidade',`<p>Seus registros são mantidos neste aparelho e, quando a conexão estiver disponível e a sincronização estiver concluída, também na sua <b>conta ESTUDNEXA</b>. Confira o indicador de nuvem antes de trocar de dispositivo. Faça backups regularmente.</p><div class="file-buttons"><button class="btn btn-outline btn-small" data-action="backup-export">Exportar dados (.json)</button><button class="btn btn-outline btn-small" data-action="backup-import">Importar backup</button><button class="btn btn-outline btn-small" data-action="csv-export">Exportar planilha (.csv)</button></div><p class="note">Evite colocar dados de pacientes. Exportações não são criptografadas. Limpar dados do navegador pode apagar seu progresso.</p>`)}</div></div>`;}
  function render(){navRender();$('top-date').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'short',day:'numeric',month:'short'}).format(new Date());if(view==='community'||view==='profile'){window.MedAtlasCommunity?.draw(view,$('main-content'));}else{$('main-content').innerHTML=({dashboard,planner,cards,quiz,errors,roadmap,progress}[view]||dashboard)();}}
  function closeMobileMenu(){document.body.classList.remove('drawer-open');const b=$('mobile-menu');if(b)b.setAttribute('aria-expanded','false');const shade=$('drawer-shade');if(shade)shade.hidden=true;}
  function goto(n){view=n;closeMobileMenu();window.scrollTo({top:0,behavior:'instant'});render();}
  function dialogHTML(title,html){$('dialog-content').innerHTML=`<h2>${title}</h2>${html}`;const d=$('app-dialog');if(!d.open)d.showModal();}
  function closeDialog(){$('app-dialog').close();}
  function subjectOptions(selected=''){return state.subjects.concat(['Cardiologia'].filter(x=>!state.subjects.includes(x))).map(s=>`<option value="${esc(s)}" ${s===selected?'selected':''}>${esc(s)}</option>`).join('');}
  function taskForm(id){let t=state.tasks.find(x=>x.id===id);dialogHTML(t?'Editar tarefa':'Adicionar tarefa',`<form id="task-form"><input type="hidden" name="id" value="${esc(t?.id||'')}"><div class="form-grid"><div class="field full-span"><label>Título da tarefa *</label><input name="title" maxlength="140" required placeholder="Ex.: Revisar insuficiência cardíaca" value="${esc(t?.title||'')}"></div><div class="field"><label>Disciplina</label><select name="subject">${subjectOptions(t?.subject||'Clínica Médica')}</select></div><div class="field"><label>Data prevista</label><input type="date" name="date" value="${esc(t?.date||nowISO())}" required></div><div class="field"><label>Duração estimada (minutos)</label><input type="number" min="5" max="600" name="minutes" value="${t?.minutes||40}" required></div></div><div class="dialog-actions"><button type="button" class="btn btn-outline" data-action="dialog-close">Cancelar</button><button class="btn btn-primary" type="submit">Salvar tarefa</button></div></form>`);}
  function manualForm(){dialogHTML('Registrar tempo de estudo',`<form id="manual-form"><div class="form-grid"><div class="field"><label>Data do estudo</label><input name="date" type="date" value="${nowISO()}" required></div><div class="field"><label>Duração (minutos)</label><input name="minutes" type="number" min="1" max="600" value="45" required></div><div class="field full-span"><label>Disciplina</label><select name="subject">${subjectOptions('Clínica Médica')}</select></div></div><div class="dialog-actions"><button class="btn btn-outline" type="button" data-action="dialog-close">Cancelar</button><button class="btn btn-primary">Registrar tempo</button></div></form>`);}
  function cardForm(){dialogHTML('Novo flashcard',`<form id="card-form"><div class="form-grid"><div class="field full-span"><label>Pergunta *</label><textarea name="front" maxlength="800" required placeholder="O que você quer recordar?"></textarea></div><div class="field full-span"><label>Resposta *</label><textarea name="back" maxlength="1500" required placeholder="Resposta concisa e clara"></textarea></div><div class="field full-span"><label>Área</label><select name="subject">${subjectOptions()}</select></div></div><div class="dialog-actions"><button type="button" class="btn btn-outline" data-action="dialog-close">Cancelar</button><button class="btn btn-primary">Salvar flashcard</button></div></form>`);}
  function questionForm(){dialogHTML('Criar questão de estudo',`<form id="question-form"><div class="form-grid"><div class="field full-span"><label>Enunciado *</label><textarea name="q" maxlength="1200" required></textarea></div>${['A','B','C','D'].map(i=>`<div class="field full-span"><label>Alternativa ${i} *</label><input name="o${i}" maxlength="450" required></div>`).join('')}<div class="field"><label>Alternativa correta</label><select name="a">${['A','B','C','D'].map((l,i)=>`<option value="${i}">${l}</option>`).join('')}</select></div><div class="field"><label>Área</label><select name="subject">${subjectOptions()}</select></div><div class="field full-span"><label>Comentário/explicação *</label><textarea name="why" maxlength="1300" required></textarea></div></div><div class="dialog-actions"><button type="button" class="btn btn-outline" data-action="dialog-close">Cancelar</button><button class="btn btn-primary">Adicionar questão</button></div></form>`);}
  function settings(){const p=state.profile;dialogHTML('Meu perfil e minhas metas',`<form id="settings-form"><div class="form-grid"><div class="field full-span"><label>Como deseja ser chamado(a)?</label><input name="name" maxlength="40" value="${esc(p.name)}" required></div><div class="field"><label>Fase da formação</label><select name="period">${Array.from({length:12},(_,i)=>`${i+1}º período`).concat(['Internato','Formado(a)']).map(x=>`<option ${x===p.period?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Objetivo principal</label><select name="track">${['Residência médica','Consolidar disciplinas','Preparação para internato','Provas da faculdade','Aprimoramento geral'].map(x=>`<option ${x===p.track?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Meta de minutos por semana</label><input type="number" name="weeklyMinutes" min="30" max="10080" value="${p.weeklyMinutes}" required></div><div class="field"><label>Meta de questões por semana</label><input type="number" name="weeklyQuestions" min="1" max="1000" value="${p.weeklyQuestions}" required></div><div class="field full-span"><label>Adicionar nova área / disciplina</label><div style="display:flex;gap:8px"><input id="new-subject" maxlength="45" placeholder="Ex.: Infectologia"><button type="button" class="btn btn-outline" data-action="subject-add">Adicionar</button></div></div><div class="full-span"><div class="chip-row">${state.subjects.map(x=>`<span class="badge">${esc(x)}</span>`).join('')}</div></div></div><div class="dialog-actions"><button type="button" class="btn btn-outline" data-action="dialog-close">Fechar</button><button class="btn btn-primary">Salvar perfil</button></div></form>`);}
  function confirmDelete(textToShow,action,id){dialogHTML('Confirmar exclusão',`<p>Deseja excluir <b>${esc(textToShow)}</b>? Esta ação não poderá ser desfeita.</p><div class="dialog-actions"><button class="btn btn-outline" data-action="dialog-close">Cancelar</button><button class="btn btn-danger" data-action="${action}" data-id="${esc(id)}">Excluir</button></div>`);}
  function download(name,content,type){let blob=new Blob([content],{type});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000);}
  async function copyReport(){const text=report();try{await navigator.clipboard.writeText(text);toast('Relatório copiado. Cole na sua conversa!');}catch{dialogHTML('Copie seu relatório',`<p>Selecione e copie o texto abaixo para compartilhar.</p><textarea style="width:100%;height:280px" readonly>${esc(text)}</textarea><div class="dialog-actions"><button class="btn btn-primary" data-action="dialog-close">Fechar</button></div>`);}}
  function toggleTimer(){if(timerUntil){timerRemaining=Math.max(0,Math.ceil((timerUntil-Date.now())/1000));timerUntil=null;clearInterval(timerInterval);}else{if(!timerRemaining)timerRemaining=timerDuration*60;timerUntil=Date.now()+timerRemaining*1000;timerInterval=setInterval(tick,250);}render();}
  function tick(){if(timerUntil){timerRemaining=Math.max(0,Math.ceil((timerUntil-Date.now())/1000));document.querySelectorAll('#timer-display').forEach(x=>x.textContent=fmtTime(timerRemaining));if(timerRemaining===0){timerUntil=null;clearInterval(timerInterval);state.sessions.push({id:uid(),date:nowISO(),minutes:timerDuration,subject:'Sessão de foco'});save();timerRemaining=timerDuration*60;render();toast(`Sessão de ${timerDuration} minutos concluída e registrada!`);}}}
  function gradeCard(grade){let c=state.cards.find(x=>x.id===selectedCard);if(!c)return;const old=Math.max(1,Number(c.interval)||1),reps=Number(c.reps)||0;let days;if(grade==='again'){days=1;c.reps=0;}else if(grade==='hard'){days=Math.max(2,Math.ceil(old*1.4));c.reps=reps+1;}else if(grade==='good'){days=reps===0?2:reps===1?4:Math.ceil(old*2.5);c.reps=reps+1;}else{days=reps===0?4:Math.ceil(old*3.2);c.reps=reps+1;}c.interval=days;c.due=plusDays(nowISO(),days);state.reviews.push({id:uid(),cardId:c.id,grade,date:nowISO()});flashFlip=false;selectedCard=null;save();render();toast('Revisão registrada!');}
  function startQuiz(){let qs=state.questions.filter(q=>quizSubject==='Todas'||q.subject===quizSubject);if(!qs.length){toast('Não há questões nesta área. Escolha outra.');return;}let ids=qs.slice();for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}currentQuiz={ids:ids.slice(0,10).map(x=>x.id),index:0,correct:0,picked:null};render();}
  document.addEventListener('change',e=>{if(e.target.id==='quiz-subject')quizSubject=e.target.value;if(e.target.id==='errors-subject'){errorSubject=e.target.value;render();}if(e.target.matches('[data-milestone]')){const id=e.target.dataset.milestone;if(e.target.checked&&!state.milestones.includes(id))state.milestones.push(id);if(!e.target.checked)state.milestones=state.milestones.filter(x=>x!==id);save();render();}});
  document.addEventListener('click',e=>{let btn=e.target.closest('button');if(!btn)return;if(btn.hasAttribute('data-nav')){goto(btn.dataset.nav);return;}let a=btn.dataset.action,id=btn.dataset.id,val=btn.dataset.value;if(!a)return;
    switch(a){
    case 'settings':settings();break;
    case 'dialog-close':closeDialog();break;
    case 'task-add':taskForm();break;
    case 'task-edit':taskForm(id);break;
    case 'task-toggle':{let t=state.tasks.find(x=>x.id===id);if(t){t.done=!t.done;t.completedAt=t.done?nowISO():null;save();render();toast(t.done?'Tarefa concluída!':'Tarefa reaberta.');}break;}
    case 'task-delete':{let t=state.tasks.find(x=>x.id===id);if(t)confirmDelete(t.title,'task-delete-confirm',id);break;}
    case 'task-delete-confirm':state.tasks=state.tasks.filter(x=>x.id!==id);save();closeDialog();render();toast('Tarefa excluída.');break;
    case 'task-filter':taskFilter=val;render();break;
    case 'manual-log':manualForm();break;
    case 'card-add':cardForm();break;
    case 'card-filter':cardFilter=val;selectedCard=null;flashFlip=false;render();break;
    case 'card-select':cardFilter='all';selectedCard=id;flashFlip=false;render();break;
    case 'card-reveal':flashFlip=true;render();break;
    case 'card-grade':gradeCard(val);break;
    case 'card-delete':{let c=state.cards.find(x=>x.id===id);if(c)confirmDelete(c.front,'card-delete-confirm',id);break;}
    case 'card-delete-confirm':state.cards=state.cards.filter(x=>x.id!==id);if(selectedCard===id)selectedCard=null;save();closeDialog();render();toast('Cartão excluído.');break;
    case 'question-add':questionForm();break;
    case 'quiz-start':startQuiz();break;
    case 'quiz-one':startQuestionSubset([id]);break;
    case 'quiz-wrong':startQuestionSubset(wrongQuestions().slice(0,10).map(q=>q.id));break;
    case 'error-note':errorNoteForm(id);break;
    case 'error-card':{const q=state.questions.find(q=>q.id===id);if(!q)break;const front=q.q,back=`Resposta: ${q.o[q.a]}. ${q.why}`;if(state.cards.some(c=>c.front===front)){toast('Este flashcard já foi criado.');break;}state.cards.push({id:uid(),front,back,subject:q.subject,due:nowISO(),interval:0,reps:0});save();toast('Flashcard criado para revisar hoje!');break;}
    case 'weekly-plan':makeWeeklyPlan();break;
    case 'csv-export':exportCSV();break;
    case 'quiz-answer':{if(!currentQuiz||currentQuiz.picked!==null)return;const q=state.questions.find(x=>x.id===currentQuiz.ids[currentQuiz.index]);if(!q)return;const pick=Number(val);if(![0,1,2,3].includes(pick))return;currentQuiz.picked=pick;if(pick===q.a)currentQuiz.correct++;state.answers.push({id:uid(),questionId:q.id,subject:q.subject,date:nowISO(),correct:pick===q.a,selected:pick});save();render();break;}
    case 'quiz-next':if(currentQuiz){currentQuiz.index++;currentQuiz.picked=null;render();}break;
    case 'quiz-quit':currentQuiz=null;render();break;
    case 'quiz-finish':currentQuiz=null;render();break;
    case 'quiz-restart':currentQuiz=null;startQuiz();break;
    case 'timer-mode':timerDuration=Number(val);timerRemaining=timerDuration*60;timerUntil=null;clearInterval(timerInterval);render();break;
    case 'timer-toggle':toggleTimer();break;
    case 'timer-reset':timerUntil=null;clearInterval(timerInterval);timerRemaining=timerDuration*60;render();break;
    case 'report-copy':copyReport();break;
    case 'report-download':download(`medatlas-relatorio-${nowISO()}.txt`,report(),'text/plain;charset=utf-8');toast('Relatório gerado.');break;
    case 'backup-export':download(`medatlas-backup-${nowISO()}.json`,JSON.stringify(state,null,2),'application/json;charset=utf-8');toast('Backup gerado. Guarde-o com segurança.');break;
    case 'backup-import':$('import-file').click();break;
    case 'subject-add':{const input=$('new-subject'),subject=input.value.trim();if(!subject)return toast('Digite o nome de uma disciplina.');if(state.subjects.some(s=>s.toLowerCase()===subject.toLowerCase()))return toast('Essa disciplina já existe.');state.subjects.push(subject);save();settings();toast('Disciplina adicionada.');break;}
    }
  });
  document.addEventListener('submit',e=>{let f=e.target;const formId=f.getAttribute('id');if(!['task-form','card-form','question-form','settings-form','manual-form','error-note-form'].includes(formId))return;e.preventDefault();let d=Object.fromEntries(new FormData(f).entries());if(formId==='error-note-form'){state.notes[d.id]=String(d.note||'').trim();save();closeDialog();render();toast('Anotação salva.');return;}if(formId==='task-form'){let title=d.title.trim();if(!title)return;let t=state.tasks.find(x=>x.id===d.id);let change={title,subject:d.subject,minutes:Number(d.minutes),date:d.date};if(t)Object.assign(t,change);else state.tasks.push({id:uid(),...change,done:false,completedAt:null});toast(t?'Tarefa atualizada.':'Tarefa adicionada.');}else if(formId==='manual-form'){state.sessions.push({id:uid(),date:d.date,minutes:Number(d.minutes),subject:d.subject});toast('Tempo de estudo registrado!');}else if(formId==='card-form'){state.cards.push({id:uid(),front:d.front.trim(),back:d.back.trim(),subject:d.subject,due:nowISO(),interval:0,reps:0});selectedCard=null;cardFilter='due';toast('Novo cartão criado.');}else if(formId==='question-form'){state.questions.push({id:uid(),q:d.q.trim(),o:['A','B','C','D'].map(x=>d['o'+x].trim()),a:Number(d.a),subject:d.subject,why:d.why.trim(),custom:true});quizSubject='Todas';toast('Questão adicionada ao banco.');}else if(formId==='settings-form'){state.profile={name:d.name.trim(),period:d.period,track:d.track,weeklyMinutes:Number(d.weeklyMinutes),weeklyQuestions:Number(d.weeklyQuestions)};toast('Seu perfil foi atualizado.');}save();closeDialog();render();});
  $('import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>3e6)throw new Error('Arquivo muito grande');const parsed=JSON.parse(await f.text());if(!valid(parsed))throw new Error('Formato de backup incompatível');if(!confirm('Importar este backup substituirá todos os dados atuais neste dispositivo. Deseja continuar?'))return;state={...parsed,version:2,notes:parsed.notes&&typeof parsed.notes==='object'&&!Array.isArray(parsed.notes)?parsed.notes:{},milestones:Array.isArray(parsed.milestones)?parsed.milestones:[]};currentQuiz=null;selectedCard=null;save();render();toast('Dados restaurados com sucesso.');}catch(err){toast('Não foi possível importar. Verifique o arquivo JSON.');}finally{e.target.value='';}});
  $('settings-button').addEventListener('click',settings);
  $('app-dialog').addEventListener('click',e=>{if(e.target===$('app-dialog'))closeDialog();});
  const mobileMenu=$('mobile-menu'),drawerShade=$('drawer-shade');
  if(mobileMenu) mobileMenu.addEventListener('click',()=>{const open=!document.body.classList.contains('drawer-open');document.body.classList.toggle('drawer-open',open);mobileMenu.setAttribute('aria-expanded',String(open));drawerShade.hidden=!open;});
  if(drawerShade)drawerShade.addEventListener('click',closeMobileMenu);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileMenu();});
  window.MedAtlasApp = {
    getState: () => JSON.parse(JSON.stringify(state)),
    replaceState: (next) => {if(!valid(next)) throw new Error('Estado incompatível'); state=next; try {localStorage.setItem(KEY,JSON.stringify(next));}catch{};currentQuiz=null;selectedCard=null;render();}
  };
  /* Salve sempre em espaço isolado por usuário; sincronize pela camada MedAtlasCloud. */
  render();
})();
